root=pathlib.Path(__file__).resolve().parents[2];out=pathlib.Path(sys.argv[1]);out.mkdir(parents=True,exist_ok=False);watcher=out/"watch-control";subprocess.run(["swiftc",str(root/"apps/desktop/check-cua-control-macos.swift"),"-o",str(watcher)],check=True,timeout=45);expected_fast_decision="已交回慢脑重新观察或规划";native=subprocess.Popen([str(watcher),str(out/"native"),expected_fast_decision,"observe-only"],stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
