 window=json.loads((out/"native/window-result.json").read_text());result={"platform":"macos","task_id":task["task_id"],"window_visible":window["visible"],"top_centered_like_region":window["top_centered_like_region"],"expected_size":window["expected_size"],"slow_brain_found":window["slow_brain_found"],"fast_brain_found":window["fast_brain_found"],"fast_decision_found":window["fast_decision_found"],"execution_found":window["execution_found"],"planned_step_found":window["planned_step_found"],"observe_only":window["observe_only"],"task_status":cancelled["status"],"executed_disposition":executed.get("disposition"),"stopped_before_all_slots":slot<8,"new_user_input_unknown_count":user_input,"passed":cancelled["status"]=="cancelled" and executed.get("disposition")=="handback" and slot<8 and user_input==0 and window["top_centered_like_region"] and window["expected_size"] and window["slow_brain_found"] and window["fast_brain_found"] and window["fast_decision_found"] and window["execution_found"] and window["planned_step_found"]};(out/"result.json").write_text(json.dumps(result,ensure_ascii=False,indent=2)+"\n");print(json.dumps(result,ensure_ascii=False));assert result["passed"],result
